#!/usr/bin/env node
// Condense one captured conversation JSONL into a readable digest.
//   node condense.mjs <file> [--mode turns|tools|all] [--max <chars per text block>]
import { createReadStream } from 'node:fs';
import { createInterface } from 'node:readline';

const [, , file, ...rest] = process.argv;
const arg = (name, dflt) => {
  const i = rest.indexOf(name);
  return i === -1 ? dflt : rest[i + 1];
};
const mode = arg('--mode', 'turns');
const max = Number(arg('--max', 1200));

const clip = (s) => {
  const t = String(s).replace(/\s+/g, ' ').trim();
  return t.length > max ? `${t.slice(0, max)} …[${t.length}]` : t;
};

const rl = createInterface({ input: createReadStream(file), crlfDelay: Infinity });
let n = 0;
for await (const line of rl) {
  if (!line.trim()) continue;
  n += 1;
  let e;
  try { e = JSON.parse(line); } catch { continue; }
  const ts = e.timestamp || e.ts || '';
  const msg = e.message || e;
  const role = e.type || msg.role || '';
  const content = msg.content;
  const parts = Array.isArray(content) ? content : (typeof content === 'string' ? [{ type: 'text', text: content }] : []);
  for (const p of parts) {
    if (p.type === 'text' && p.text) {
      if (mode === 'tools') continue;
      console.log(`\n[${n}] ${ts} ${role.toUpperCase()}: ${clip(p.text)}`);
    } else if (p.type === 'thinking' && p.thinking) {
      if (mode !== 'all') continue;
      console.log(`\n[${n}] ${ts} THINKING: ${clip(p.thinking)}`);
    } else if (p.type === 'tool_use') {
      if (mode === 'turns') continue;
      console.log(`[${n}] ${ts} TOOL ${p.name}: ${clip(JSON.stringify(p.input)).slice(0, 300)}`);
    } else if (p.type === 'tool_result') {
      if (mode !== 'all') continue;
      const c = typeof p.content === 'string' ? p.content : JSON.stringify(p.content);
      console.log(`[${n}] ${ts} RESULT${p.is_error ? '(ERR)' : ''}: ${clip(c).slice(0, 400)}`);
    }
  }
}

